import {validateInvestments} from './investment-schema.mjs';
import {validateSettlements} from './settlement-schema.mjs';
import {validateInvoices} from './invoice-schema.mjs';
import {validateFeatures,transactionMeta,validateFeatureLinks} from './schema.mjs';
export const CATEGORIES=['餐飲','交通','購物','生活','娛樂','健康','居住','學習','手續費／利息','其他'];
export const TYPE_LABEL={expense:'支出',income:'收入',transfer:'轉帳',refund:'退款'};
export const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const uid=()=>{if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');return [h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20)].join('-')};
export const cents=v=>{const n=Number(v);if(!Number.isFinite(n)||Math.abs(n)>1e10)throw Error('請輸入有效金額');return Math.round(n*100)};
export const money=n=>'NT$'+new Intl.NumberFormat('zh-TW',{maximumFractionDigits:2}).format(n/100);
export function validDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===v}
export function fresh(){return {version:1,accounts:[{id:'cash',name:'現金',kind:'cash',opening:0},{id:'bank',name:'銀行帳戶',kind:'bank',opening:0},{id:'card',name:'信用卡',kind:'card',opening:0}],transactions:[],budgets:{},defaultBudget:3000000}}
export function validateTx(t,state){if(!t||!Object.hasOwn(TYPE_LABEL,t.type))throw Error('交易類型不正確');if(!Number.isSafeInteger(t.amount)||t.amount<=0||t.amount>1e12)throw Error('金額必須大於 0，最多兩位小數');if(!validDate(t.date))throw Error('請選擇有效日期');if(!state.accounts.some(a=>a.id===t.account))throw Error('請選擇帳戶');if(t.type==='transfer'&&(!state.accounts.some(a=>a.id===t.toAccount)||fundingAccount(state,t.account)===fundingAccount(state,t.toAccount)))throw Error('轉出與轉入帳戶必須不同');if(typeof t.note!=='string'||!t.note.trim()||t.note.length>200)throw Error('請填寫名稱（最多200字）');if(!categoryList(state).includes(t.category))throw Error('請選擇分類');return t}
export const isLinked=a=>a.kind==='mobile'&&a.paymentMode==='linked';
export function fundingAccount(state,id){const a=state.accounts.find(a=>a.id===id);return a&&isLinked(a)?a.linkedAccount:id}
export function totalBalance(state){return state.accounts.filter(a=>!isLinked(a)).reduce((s,a)=>s+balance(state,a.id),0)}
export function balance(state,id){const source=fundingAccount(state,id);return state.transactions.reduce((s,t)=>s+(fundingAccount(state,t.account)===source?(t.type==='expense'||t.type==='transfer'?-t.amount:t.amount):0)+(t.type==='transfer'&&fundingAccount(state,t.toAccount)===source?t.amount:0),state.accounts.find(a=>a.id===source)?.opening||0)}

export const categoryList=state=>[...new Set([...CATEGORIES,...(state.features?.categories||[])])];
export function summary(state,month,options={}){let expense=0,income=0;const categories=Object.fromEntries(categoryList(state).map(c=>[c,0]));for(const t of state.transactions.filter(t=>inPeriod(t.date,month,options.cycleDay||1)&&(!options.bookId||(t.bookId||'personal')===options.bookId))){if(t.type==='income')income+=t.amount;if(t.type==='expense'||t.type==='refund'){const n=t.type==='refund'?-t.amount:t.amount;expense+=n;categories[t.category]+=n}}return {expense,income,categories,net:income-expense,budget:state.budgets[month]??state.defaultBudget}}
export function validateBackup(raw){if(!raw||raw.version!==1||!Array.isArray(raw.accounts)||!raw.accounts.length||raw.accounts.length>100||!Array.isArray(raw.transactions)||raw.transactions.length>100000)throw Error('不是有效的日常有餘備份');const ids=new Set();const accounts=raw.accounts.map(a=>{if(!a||typeof a.id!=='string'||ids.has(a.id)||typeof a.name!=='string'||!a.name.trim()||a.name.length>40||!['cash','bank','card','mobile','bnpl','receivable'].includes(a.kind)||!Number.isSafeInteger(a.opening)||Math.abs(a.opening)>1e12)throw Error('備份帳戶資料不正確');ids.add(a.id);const account={id:a.id,name:a.name,kind:a.kind,opening:a.opening};if(['card','bnpl'].includes(a.kind)&&a.creditLimit!==undefined&&a.creditLimit!==null){if(!Number.isSafeInteger(a.creditLimit)||a.creditLimit<0||a.creditLimit>1e12)throw Error('信用額度必須是非負金額，最多兩位小數');account.creditLimit=a.creditLimit}if(a.kind==='mobile'){if(a.paymentMode&&!['balance','linked'].includes(a.paymentMode))throw Error('行動支付付款方式不正確');account.paymentMode=a.paymentMode||'balance';if(account.paymentMode==='linked'){if(typeof a.linkedAccount!=='string'||a.opening!==0)throw Error('綁定付款的期初餘額必須為0，請在來源帳戶設定');account.linkedAccount=a.linkedAccount}}return account});for(const a of accounts.filter(isLinked)){if(!accounts.some(x=>x.id===a.linkedAccount&&['bank','card','bnpl'].includes(x.kind)))throw Error('行動支付必須連結有效的銀行、信用卡或先買後付帳戶')}const state={version:1,accounts,transactions:[],budgets:{},defaultBudget:raw.defaultBudget};if(!Number.isSafeInteger(state.defaultBudget)||state.defaultBudget<0||state.defaultBudget>1e12)throw Error('預算格式不正確');for(const [k,v] of Object.entries(raw.budgets||{})){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(k)||!Number.isSafeInteger(v)||v<0||v>1e12)throw Error('月份預算格式不正確');state.budgets[k]=v}if(raw.features)state.features=validateFeatures(raw.features,accounts,raw.transactions,CATEGORIES);const txids=new Set();state.transactions=raw.transactions.map(t=>{validateTx(t,state);if(typeof t.id!=='string'||txids.has(t.id))throw Error('交易編號重複或缺少');txids.add(t.id);return {id:t.id,type:t.type,amount:t.amount,date:t.date,note:t.note,category:t.category,account:t.account,toAccount:t.type==='transfer'?t.toAccount:null,...transactionMeta(t,state)}});if(state.features){for(const item of state.features.trash){validateTx(item.tx,state);transactionMeta(item.tx,state)}}validateFeatureLinks(state);if(raw.invoices!==undefined)state.invoices=validateInvoices(raw.invoices);if(raw.settlements!==undefined)state.settlements=validateSettlements(raw.settlements,state);else if(state.transactions.some(t=>t.origin?.kind?.startsWith('advance')))throw Error('備份缺少代墊關聯資料');if(raw.investments!==undefined)state.investments=validateInvestments(raw.investments);return state}
export function parseLocal(text,state,date=today()){
 const parts=text.replace(/(\d),(?=\d{3}(?:\D|$))/g,'$1').split(/[，,。；;\n]+/).map(x=>x.trim()).filter(Boolean);const result=[];
 for(const part of parts){if((/還款|繳款|繳費|繳卡費|儲值|加值/.test(part)||(/轉帳/.test(part)&&!/轉帳手續費/.test(part))))throw Error('還款、繳費或儲值請使用「轉帳」，避免重複計算支出');const matches=[...part.matchAll(/(?:NT\$|\$)?\s*(\d+(?:\.\d{1,2})?)\s*(?:元|塊)?/g)];if(matches.length!==1)throw Error('每筆請只放一個金額，並以逗號分開；日期請在預覽調整');const m=matches[0];const amount=cents(m[1]);const account=state.accounts.find(a=>part.includes(a.name))||state.accounts.find(a=>/刷卡|信用卡/.test(part)&&a.kind==='card')||state.accounts[0];const type=/退款|退費/.test(part)?'refund':/薪水|薪資|獎金|收入|入帳/.test(part)?'income':'expense';const rules=[['手續費／利息',/手續費|利息|服務費|處理費|遲延費/],['餐飲',/餐|飯|咖啡|茶|飲料|便當|早餐|午餐|晚餐/],['交通',/捷運|車|加油|交通|悠遊/],['購物',/買|衣|鞋|購物/],['生活',/水電|電話|網路|日用/],['娛樂',/遊戲|電影|Netflix|娛樂/i],['健康',/醫|藥|健身/],['居住',/房租|房貸/],['學習',/書|課|學習/]];const category=rules.find(([,re])=>re.test(part))?.[0]||'其他';const note=(part.slice(0,m.index)+part.slice(m.index+m[0].length)).replace(/今天|今日|昨天|昨日|現金|刷卡|信用卡/g,'').trim()||TYPE_LABEL[type];let d=date;if(/昨天|昨日/.test(part)){const x=new Date(date+'T12:00:00Z');x.setUTCDate(x.getUTCDate()-1);d=x.toISOString().slice(0,10)}result.push(validateTx({id:uid(),type,amount,date:d,note,category,account:account.id,toAccount:null},state))}if(!result.length)throw Error('請輸入內容，例如：午餐150現金，咖啡120刷卡');return result;
}
export function demoState(){const s=fresh(),month=today().slice(0,7),end=Number(today().slice(-2));s.accounts[0].opening=520000;s.accounts[1].opening=12800000;s.accounts[2].opening=-186000;const items=[['薪資入帳',52000,'income','其他','bank'],['房租',10000,'expense','居住','bank'],['午餐',150,'expense','餐飲','cash'],['咖啡',120,'expense','餐飲','card'],['捷運加值',500,'expense','交通','cash'],['超市採買',1680,'expense','生活','card'],['週末聚餐',1290,'expense','餐飲','card'],['運動用品',2490,'expense','購物','card'],['線上課程',1990,'expense','學習','card'],['書籍',420,'expense','學習','cash']];s.transactions=items.map(([note,n,type,category,account],i)=>({id:uid(),note,amount:cents(n),type,category,account,toAccount:null,date:month+'-'+String(Math.max(1,end-Math.floor(i/2))).padStart(2,'0')}));return s}
export function csv(state){const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';return '\uFEFF'+[['日期','類型','項目','分類','金額TWD','帳戶','轉入帳戶','帳本','標籤'],...state.transactions.map(t=>[t.date,TYPE_LABEL[t.type],t.note,t.category,(t.amount/100).toFixed(2),state.accounts.find(a=>a.id===t.account)?.name,state.accounts.find(a=>a.id===t.toAccount)?.name||'',state.features?.books.find(b=>b.id===(t.bookId||'personal'))?.name||'生活',(t.tags||[]).join('、')])].map(r=>r.map(cell).join(',')).join('\r\n')}

export function cycleBounds(month,day=1){const anchor=(m,d)=>{const x=new Date(m+'-01T12:00:00Z');x.setUTCMonth(x.getUTCMonth()+d);const y=x.getUTCFullYear(),mo=x.getUTCMonth(),last=new Date(Date.UTC(y,mo+1,0)).getUTCDate();return y+'-'+String(mo+1).padStart(2,'0')+'-'+String(Math.min(day,last)).padStart(2,'0')};return {start:anchor(month,0),end:anchor(month,1)}}
export function inPeriod(date,month,day=1){const p=cycleBounds(month,day);return date>=p.start&&date<p.end}
